import cv2,numpy as np
im=cv2.imread('first_frame.png');h,w=im.shape[:2]
mask=cv2.imread('.tmp/mask3.png',0)
base=cv2.inpaint(im,mask,5,cv2.INPAINT_TELEA)
# clamp to inpaint but use patchmatch-like column copies from outside. create candidate backgrounds per region by shifting source patch
out=base.copy()
# For wall use column x +/- 30 from same y, choose one with least mask coverage and blend horizontally
for y in range(0,54):
 xs=np.where(mask[y]>0)[0]
 if not len(xs): continue
 s,e=xs.min(),xs.max()
 for x in range(s,e+1):
  best=[]
  for d in range(20,70,4):
   for xx in [x-d,x+d]:
    if 0<=xx<w and mask[y,xx]==0: best.append((abs(d),im[y,xx]))
  if best:
   best.sort(key=lambda z:z[0]);out[y,x]=best[0][1]
# table rows shift vertically from known clean y above/below
for y in range(54,74):
 xs=np.where(mask[y]>0)[0]
 if not len(xs):continue
 for x in xs:
  # copy nearby known at same y horizontally or from row 65 clean near edge
  for d in range(1,30):
   xx=x-d if x<129 else x+d
   if 0<=xx<w and mask[y,xx]==0:
    out[y,x]=im[y,xx];break
out[mask==0]=im[mask==0]
cv2.imwrite('.tmp/plate9.png',out)
